WITH UserVoteStats AS (SELECT u.Id AS UserId, u.DisplayName, SUM(CASE WHEN v.VoteTypeId = 2 THEN 1 ELSE 0 END) AS UpVotes, SUM(CASE WHEN v.VoteTypeId = 3 THEN 1 ELSE 0 END) AS DownVotes, COUNT(DISTINCT p.Id) AS TotalPosts, AVG(COALESCE(p.ViewCount, 0)) AS AvgViews FROM Users AS u LEFT JOIN Votes AS v ON u.Id = v.UserId LEFT JOIN Posts AS p ON v.PostId = p.Id GROUP BY u.Id, u.DisplayName), RecentPosts AS (SELECT Id, Title, CreationDate, OwnerUserId, ViewCount, ROW_NUMBER() OVER (PARTITION BY OwnerUserId ORDER BY CreationDate DESC NULLS FIRST) AS PostOrder FROM Posts WHERE CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '30' DAYS), UserBadges AS (SELECT b.UserId, COUNT(b.Id) AS BadgeCount, GROUP_CONCAT(b.Name, ', ') AS BadgeNames FROM Badges AS b GROUP BY b.UserId), UserPostStats AS (SELECT u.DisplayName, COUNT(DISTINCT rp.Id) AS RecentPostCount, COALESCE(ubs.BadgeCount, 0) AS BadgeCount, COALESCE(ubs.BadgeNames, 'None') AS BadgeNames FROM Users AS u LEFT JOIN RecentPosts AS rp ON u.Id = rp.OwnerUserId LEFT JOIN UserBadges AS ubs ON u.Id = ubs.UserId GROUP BY u.DisplayName, ubs.BadgeCount, ubs.BadgeNames) SELECT uvs.UserId, uvs.DisplayName, uvs.UpVotes, uvs.DownVotes, ups.RecentPostCount, ups.BadgeCount, ups.BadgeNames, COALESCE(uvs.AvgViews, 0) AS AverageViews, CASE WHEN uvs.TotalPosts = 0 THEN 'No Posts' ELSE 'Has Posts' END AS PostStatus FROM UserVoteStats AS uvs JOIN UserPostStats AS ups ON uvs.DisplayName = ups.DisplayName ORDER BY uvs.UpVotes DESC NULLS FIRST, ups.RecentPostCount DESC NULLS FIRST LIMIT 100